// Security headers and caching for the /frontend2 app. Shared by both of its behaviours;
// `uri` is already the rewritten one, because the viewer-request function runs first.
//
// The CSP is hash-based, unlike the Angular app's nonce-based policy: frontend2's build
// emits no inline script or style, so nothing has to be minted per request and the app
// shell can be served straight from S3 instead of generated by a Lambda@Edge. The policy
// is substituted at synth time from frontend2/dist/csp-hashes.json, which `vite preview`
// also serves — see the comment above CSP_HASHES_FILE in frontend2/vite.config.ts.
function handler(event) {
    const response = event.response;
    const headers = response.headers;
    const uri = event.request.uri;

    headers['strict-transport-security'] = {value: 'max-age=63072000; includeSubDomains; preload'};
    headers['x-content-type-options'] = {value: 'nosniff'};
    headers['x-frame-options'] = {value: 'SAMEORIGIN'};

    let cacheControl;
    if (uri.startsWith('/frontend2/assets/')) {
        // Content-hashed filenames, so they can never go stale.
        cacheControl = 'immutable, max-age=31536000';
    } else {
        // The app shell, which every deploy replaces and every deep link resolves to.
        cacheControl = 'no-store';
        // Double quotes: every source expression in the policy is single-quoted.
        headers['content-security-policy'] = {value: "{{CSP}}"};
    }

    const status = response.statusCode;
    if (status === 200 || status === 301 || status === 304) {
        headers['cache-control'] = {value: cacheControl};
    }

    return response;
}
